-- Origin SQL:
SELECT * FROM a NATURAL JOIN b;
SELECT * FROM a NATURAL LEFT OUTER JOIN b;
SELECT * FROM a GLOBAL NATURAL FULL JOIN b;
SELECT * FROM a PASTE JOIN b;
SELECT * FROM a AS x GLOBAL PASTE JOIN b AS y;
SELECT count() FROM (SELECT * FROM t1 PASTE JOIN t2);
SELECT * FROM a AS paste JOIN b ON a.x = paste.x;


